{
  "name": "opencode-thinking-meter",
  "version": "0.1.0",
  "description": "OpenCode TUI plugin: counts the turns cut off mid-thought, says whether the output cap or the context window did it, and shows what thinking costs per turn and after which tool.",
  "type": "module",
  "license": "MIT",
  "author": {
    "name": "Tanner Bruhn",
    "url": "https://github.com/tannerbruhn"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/tannerbruhn/opencode-thinking-meter.git"
  },
  "homepage": "https://github.com/tannerbruhn/opencode-thinking-meter#readme",
  "bugs": {
    "url": "https://github.com/tannerbruhn/opencode-thinking-meter/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-tui",
    "tui",
    "thinking",
    "reasoning",
    "truncation",
    "context-window",
    "tokens",
    "sidebar",
    "ollama",
    "llama.cpp"
  ],
  "oc-plugin": [
    "tui"
  ],
  "exports": {
    "./tui": {
      "import": "./dist/tui.js"
    }
  },
  "files": [
    "dist",
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "node scripts/build.mjs",
    "test": "node --test test/",
    "prepublishOnly": "npm run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.0",
    "@opentui/solid": "*",
    "solid-js": "*"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@babel/core": "^7.29.7",
    "@babel/preset-typescript": "^7.29.7",
    "babel-preset-solid": "^1.9.15"
  },
  "engines": {
    "opencode": ">=1.18.18"
  }
}
